package com.opensync.gateway.ai;
import com.fasterxml.jackson.databind.*;import com.opensync.contracts.*;import java.time.Duration;import java.util.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.http.client.SimpleClientHttpRequestFactory;import org.springframework.stereotype.Component;import org.springframework.web.client.RestClient;
@Component @ConditionalOnProperty(name="opensync.llm.provider",havingValue="anthropic")
public class AnthropicLlmClient implements LlmClient{
 private final RestClient client;private final ObjectMapper json;private final String model;
 public AnthropicLlmClient(ObjectMapper j,@Value("${opensync.llm.anthropic.base-url:https://api.anthropic.com}") String url,@Value("${opensync.llm.anthropic.api-key:}") String key,@Value("${opensync.llm.anthropic.model:claude-compatible}") String model){if(key.isBlank())throw new IllegalStateException("ANTHROPIC_API_KEY is required when LLM_PROVIDER=anthropic");var f=new SimpleClientHttpRequestFactory();f.setConnectTimeout(Duration.ofSeconds(3));f.setReadTimeout(Duration.ofSeconds(20));client=RestClient.builder().requestFactory(f).baseUrl(url).defaultHeader("x-api-key",key).defaultHeader("anthropic-version","2023-06-01").build();json=j;this.model=model;}
 public SchemaMappingSuggestion suggestMapping(JsonNode p,CanonicalSchema s){return call("Return only JSON matching SchemaMappingSuggestion. Allowed transformations: "+Arrays.toString(TransformationType.values())+". Schema: "+s+". Sample: "+p,SchemaMappingSuggestion.class);}
 public FailureExplanation explainFailure(FailureContext c){return call("Return only a JSON failure explanation. Do not change data: "+c,FailureExplanation.class);}
 private <T>T call(String prompt,Class<T> type){var body=Map.of("model",model,"max_tokens",1500,"messages",List.of(Map.of("role","user","content",prompt)));var response=client.post().uri("/v1/messages").body(body).retrieve().body(JsonNode.class);try{return json.readValue(response.at("/content/0/text").asText(),type);}catch(Exception e){throw new IllegalStateException("Invalid structured LLM response",e);}}
}
